theorem trans {ω₁ ω₂ ω₃ : ScalarCocycle G}
    (h₁₂ : CohomologousTo ω₁ ω₂) (h₂₃ : CohomologousTo ω₂ ω₃) :
    CohomologousTo ω₁ ω₃

lemma ScalarCocycle.commPhase_eq_of_cohomologousTo {ω₁ ω₂ : ScalarCocycle G}
    (H : ScalarCocycle.CohomologousTo ω₁ ω₂) {g k : G} (hgk : g * k = k * g) :
    ScalarCocycle.commPhase ω₁ g k = ScalarCocycle.commPhase ω₂ g k

theorem ScalarCocycle.isNontrivialClass_of_commPhase_ne_one {ω : ScalarCocycle G}
    {g h : G} (hgh : g * h = h * g) (hne : ScalarCocycle.commPhase ω g h ≠ 1) :
    ScalarCocycle.IsNontrivialClass ω

theorem ScalarCocycle.CohomologousTo.pullback {ω₁ ω₂ : ScalarCocycle G}
    (h : ω₁.CohomologousTo ω₂) (f : K →* G) :
    (ω₁.pullback f).CohomologousTo (ω₂.pullback f)

theorem ScalarCocycle.IsCocycle.coboundary_mul {ω : ScalarCocycle G}
    (hω : ω.IsCocycle) (φ : G → ℂˣ) :
    ScalarCocycle.IsCocycle (fun a b ↦ φ a * φ b * (φ (a * b))⁻¹ * ω a b)

theorem one_le_finrank_commonFixedSubmodule {ι : Sort*} (f : ι → W →ₗ[K] W) {v : W}
    (hv : v ∈ commonFixedSubmodule f) (hv0 : v ≠ 0) :
    1 ≤ Module.finrank K (commonFixedSubmodule f)

theorem reaches_reverse_of_edge_returns
    (hreturn : ∀ {a b : V}, r a b → Reaches r b a) {a b : V}
    (w : DirectedWalk r a b) : Reaches r b a

theorem cycleWeightSum_eq_card_loop {w : V → V → ℕ}
    (hconst : HasEventuallyConstantCycleWeightSum w) {N : ℕ} (hN : 0 < N) :
    cycleWeightSum w hN = Fintype.card (Loop w)

theorem cycleWeight_eq_one {w : V → V → ℕ}
    (hconst : HasEventuallyConstantCycleWeightSum w) {K : ℕ}
    (hK : 0 < K) (x : Fin K → V) (hx : cycleWeight w hK x ≠ 0) :
    cycleWeight w hK x = 1

theorem cycleWeight_repeat (w : V → V → ℕ) {N m : ℕ}
    (hN : 0 < N) (hm : 0 < m) (x : Fin N → V) :
    cycleWeight w (Nat.mul_pos hm hN) (Fin.repeat m x) = cycleWeight w hN x ^ m

theorem cycle_eq_constant {w : V → V → ℕ}
    (hconst : HasEventuallyConstantCycleWeightSum w) {K : ℕ}
    (hK : 0 < K) (x : Fin K → V) (hx : cycleWeight w hK x ≠ 0) :
    ∀ i : Fin K, x i = x ⟨0, hK⟩

theorem cyclicEdgeWeight_eq_one {w : V → V → ℕ}
    (hconst : HasEventuallyConstantCycleWeightSum w) {N : ℕ}
    (hN : 0 < N) (x : Fin N → V) (hx : cycleWeight w hN x ≠ 0)
    (i : Fin N) :
    w (x i) (x (next hN i)) = 1

theorem trans {ω η θ : ScalarThreeCochain G}
    (hωη : CohomologousTo ω η) (hηθ : CohomologousTo η θ) :
