theorem IsInverseNormalized.mul {β₁ β₂ : ScalarCocycle G}
    (hβ₁ : β₁.IsInverseNormalized) (hβ₂ : β₂.IsInverseNormalized) :
    (β₁ * β₂).IsInverseNormalized

theorem sigma_eq_div {L : LSymbol G X} {ω : ScalarThreeCochain G}
    (hL : IsCompatible L ω) (hLn : IsNormalized L) (x : X) (g : G) :
    ScalarThreeCochain.sigma ω g = L x g⁻¹ g / L (g • x) g g⁻¹

theorem eq_smul_transpose_of_map_star_mul_eq_smul_one {x : Matrix m m ℂ}
