theorem factorization_comparison_of_one_sided_inverses
    {α β βt γ 𝕜 : Type*} [Fintype α] [Fintype β] [Fintype βt] [Fintype γ]
    [DecidableEq β] [DecidableEq βt] [Semiring 𝕜]
    {X : Matrix α β 𝕜} {Xt : Matrix α βt 𝕜}
    {Y : Matrix β γ 𝕜} {Yt : Matrix βt γ 𝕜}
    {Lt : Matrix βt α 𝕜} {R : Matrix γ β 𝕜}
    (hfac : X * Y = Xt * Yt) (hleft : Lt * Xt = 1) (hright : Y * R = 1) :
    Lt * X = Yt * R ∧ X = Xt * (Lt * X) ∧ Yt = (Lt * X) * Y

theorem HasCommutingParentHam.mem_ground_iff {P_K : E →ₗ[ℂ] E}
    (h : HasCommutingParentHam P_K) (v : E) :
    P_K v = v ↔ h.P_AX v = v ∧ h.P_XB v = v

theorem HasCommutingParentHam.pAX_comp_pK {P_K : E →ₗ[ℂ] E}
    (h : HasCommutingParentHam P_K) :
    h.P_AX ∘ₗ P_K = P_K

theorem HasCommutingParentHam.pK_comp_pAX {P_K : E →ₗ[ℂ] E}
    (h : HasCommutingParentHam P_K) :
    P_K ∘ₗ h.P_AX = P_K

theorem HasCommutingParentHam.pK_comp_pXB {P_K : E →ₗ[ℂ] E}
    (h : HasCommutingParentHam P_K) :
    P_K ∘ₗ h.P_XB = P_K

theorem HasCommutingParentHam.pK_idem {P_K : E →ₗ[ℂ] E}
    (h : HasCommutingParentHam P_K) :
